VO = {"LC": VO_LC, "YHY": VO_YHY, "YJ-ES": VO_YJES}

# ── 画外音标记（R-026a · 2026-10-23 声音设计岗）────────────────────────────────
#   字段名与措辞**沿用全厂既定写法**（D16 `subtitle_style.golden3s_first_line.delivery`，
#   D16 U01 ep3 样板同措辞），**不新造字段名**。
#   D15 schema（schema.json D15 段）的 voice_over[] 条目为自由对象、未设 additionalProperties:false
#   ⇒ 新增该字段**不需要改 schema**（故本岗不动 03_规格/**）。
#   适用：首句说话人在 D11 镜1 不在场者 —— 按 D11 镜1 注记「D15 按画外音／主观声处理」在 D15 侧登记。
DELIVERY_VO = "画外音（人物不出画，首帧给最强符号）"
# ── Q104 三档口径（企划合规 D18 v1.117 登记 · 2026-10-23）──────────────────────
#   画外音 `delivery` 按「**角色身份是否在画幅内可辨识**」分三档，**不按「人物剪影是否在画幅内」**：
#     第一档「人物不出画」＝该角色完全没有任何形象出现在画幅内（纯环境／空镜／他人背影）；
#     第二档「身份不出画」＝该角色在画幅内以可辨识形象出现，但身份不可辨识（如无面部剪影）；
#     第三档「主观声」    ＝该角色以内心声／主观声出现且画幅内无其任何形象。
#   ep006 镜1 属**第二档**：D11 U01 v1.14 该镜 visual_facts＝「厂房暗处的一道剪影暴起冲出……
#   机位随冲势起伏但不贴近人物面部」，D12 卡 C-021 `params.seed_strategy`＝「角色域 seed 固定
#   LC:110101」⇒ 陆沉（LC）确实在画幅内，只是不给面部／不给身份锚点。
#   「首帧给最强符号」是独立于三档的通用约束、**不随档位变**（Q104 ③）⇒ 三档字面均保留该半句。
DELIVERY_VO_IDENTITY = "画外音（身份不出画，首帧给最强符号）"
MIX_VO_SUFFIX = "本条作画外音：按主观声处理，画面内无该角色口型，人物不出画。"


def vo(char_id, ep, line_idx, shot_id, in_sec, out_sec, tone, extra=None, delivery=None, mix_extra=None):
    """voice_over 条目：时码与 D16 对白字幕进出严格一致

    delivery：画外音标记（R-026a）。传值则本条登记 `delivery` 字段（沿用 D16 同名字段与措辞），
    并在 mix 末追加画外音处理句（人物不出画、按主观声处理、画面内无口型）。
    mix_extra：追加在本条 mix 末尾的口径补充句（用于登记与 delivery 字面的差异等，不改字段名）。
    """
    v = VO[char_id]
    mix = "人声轨独立成轨；起音前 0.2s 环境层与能量层压低 6dB，收音后 0.3s 渐变恢复；字幕不得早于配音起音，出点不早于配音收音。"
    if delivery:
        mix = mix[:-1] + "；" + MIX_VO_SUFFIX
    if mix_extra:
        mix = mix + mix_extra
    d = {
        "char_id": char_id,
        "ep": ep,
        "line_ref": "D09 ep%d #%d" % (ep, line_idx),
        "shot_id": shot_id,
        "at_sec": in_sec,
        "dur_sec": round(out_sec - in_sec, 2),
        "voice_lock": v["voice_lock"],
        "pace": v["pace"],
        "tone": tone,
    }
    if delivery:
        d["delivery"] = delivery
    d.update({
        "level_db": v["level_db"],
        "mix": mix,
        "avoid": v["avoid"],
    })
    if extra:
        d.update(extra)
    return d


def sfx(shot_id, g, at, dur, event, typ, level, mix=None):
    d = {
        "shot_id": shot_id,
        "global_shot_no": g,
        "at_sec": at,
        "dur_sec": dur,
        "event": event,
        "type": typ,
        "level_db": level,
    }
    if mix:
        d["mix"] = mix
    return d


def foley(shot_id, g, at, dur, event, level, mix=None):
    d = {
        "shot_id": shot_id,
        "global_shot_no": g,
        "at_sec": at,
        "dur_sec": dur,
        "event": event,
        "type": "拟音",
        "level_db": level,
    }
    if mix:
        d["mix"] = mix
    return d


def bgm(seg, name, s, e, goal, emotion, intensity, motif, arrangement):
    return {
        "segment": seg,
        "segment_name": name,
        "start_sec": s,
        "end_sec": e,
        "emotion_goal_ref": goal,
        "emotion": emotion,
        "intensity": intensity,
        "motif": motif,
        "arrangement": arrangement,
    }


